#!/usr/bin/env bash
# @generated by @metaobjectsdev/pack-cloudflare (cloudflare-doctor) — hand edits are kept by a three-way merge on regeneration; meta verify --codegen checks only the generated parts.
# Checks app.client acme::help::Help.site on Cloudflare against the model, for one environment, by name only:
# the deploy token and account id are in the vault; every secret the model declares is in the vault
# and on the Pages project's environment its branch serves (production or preview); each domain answers.
# Exits 1 when a check fails. It prints names, never a value.
#
# Needs: keys-axi, jq, curl, and what deploy/cloudflare/wrangler.sh needs.
#
#   bash deploy/cloudflare/doctor.sh <environment>
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 2

ENVIRONMENT="${1:-}"
FAIL=0
ok() { echo "ok   $*"; }
bad() { echo "FAIL $*"; FAIL=1; }
KEYS_AXI="${KEYS_AXI:-$(command -v keys-axi || echo "$HOME/.local/bin/keys-axi")}"
[ -x "$KEYS_AXI" ] || { echo "doctor: keys-axi is not installed" >&2; exit 2; }
for tool in jq curl npx; do
  command -v "$tool" >/dev/null || { echo "doctor: $tool is not installed" >&2; exit 2; }
done

# in_vault <vault project> <vault environment> <NAME>...
in_vault() {
  local names
  names=$("$KEYS_AXI" ls --project "$1" --env "$2" --json | jq -r '.secrets[].name') || { bad "cannot list vault scope $1/$2"; return; }
  local where="$1/$2"; shift 2
  for n in "$@"; do
    if grep -Fxq -e "$n" <<<"$names"; then ok "$n is in the vault ($where)"; else bad "$n is not in the vault ($where)"; fi
  done
}

# on_cloudflare <Pages project> <Pages environment> <NAME>...
on_cloudflare() {
  local names
  names=$(bash deploy/cloudflare/wrangler.sh "$ENVIRONMENT" pages secret list --project-name "$1" --env "$2" 2>/dev/null | sed -n 's/^ *- \([A-Za-z0-9_]*\):.*/\1/p') || { bad "cannot list the secrets of Pages project $1, $2 environment"; return; }
  local where="Pages project $1, $2 environment"; shift 2
  for n in "$@"; do
    if grep -Fxq -e "$n" <<<"$names"; then ok "$n is set on $where"; else bad "$n is declared and not set on $where (run deploy/cloudflare/sync-secrets.sh)"; fi
  done
}

# answers <url>
answers() {
  if curl -fsS -o /dev/null --max-time 10 "$1"; then ok "$1 answers"; else bad "$1 does not answer 2xx"; fi
}

case "$ENVIRONMENT" in
  production)
    in_vault acme-deploy dev ACME_PAGES_TOKEN CLOUDFLARE_ACCOUNT_ID
    in_vault acme-help prod SEARCH_API_KEY
    on_cloudflare help-site production SEARCH_API_KEY
    answers https://help.example.com/
    ;;
  preview)
    in_vault acme-deploy dev ACME_PAGES_TOKEN CLOUDFLARE_ACCOUNT_ID
    in_vault acme-help-preview preview SEARCH_API_KEY
    on_cloudflare help-site preview SEARCH_API_KEY
    ;;
  *) echo 'usage: bash deploy/cloudflare/doctor.sh <environment> (environments: production, preview)' >&2; exit 2 ;;
esac

exit "$FAIL"
